import{z as p,x as E,o as t,c as D,q as i,j as n,D as s,d as r,s as o,S as d,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"光模块与 WDM","description":"","frontmatter":{"title":"光模块与 WDM","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/optical-transceivers-wdm.md","filePath":"cs/optical-transceivers-wdm.md","lastUpdated":1791063341000}'),m={name:"cs/optical-transceivers-wdm.md"};function A(B,a,P,M,C,c){const l=E("Mermaid");return t(),D("div",null,[a[2]||(a[2]=i('<h1 id="光模块与-wdm" tabindex="-1">光模块与 WDM <a class="header-anchor" href="#光模块与-wdm" aria-label="Permalink to &quot;光模块与 WDM&quot;">​</a></h1><div class="epigraph"><p>可插拔模块把光电转换收成一块；波分复用让同一根玻璃同时走多个波长，容量按通道数加。</p><footer>—— 据 ITU-T G.694.1 DWDM 栅格；IEEE 802.3 光口条款；SFF-8472 / CMIS 管理接口整理</footer></div><p><a href="/cs/copper-fiber-media">上一课</a>给出光纤损伤。缺口是<strong>如何把电符号变成光、如何共享一根纤</strong>：<a href="/cs/modulation-symbol-rate">调制</a> 在模块里完成；WDM 把 \\(B\\) 切成波长通道。本课不把以太网速率年表写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>交换机 ASIC 出的是电 SerDes。SFP/QSFP 一类模块：电口标准化，光口按距离选 LR/ER/ZR。同一笼子可换灰光（一波长）或彩光（固定波长）。WDM：CWDM 间隔宽、无源便宜；DWDM 栅格密、要稳频与放大。容量近似「每波长的 \\(C\\) × 波长数」，受滤波器串扰与非线性限制，不是无限乘法。</p><p>不要把光模块当路由器：它不查 IP，只转换一跳波形。</p><p><span class="marginnote">G.694.1 定义频率栅格。数据中心 40/100G 常用并行多纤（SR4）而非一开始就 DWDM。本课不讲相干 DSP 全部均衡器。</span></p><p><span class="marginnote">术语翻译：灰光 = 一根纤只走一个波长，即普通模块；彩光 = 波长按标准栅格固定选定，多路合进同一根纤。CWDM 间隔宽、器件无源便宜，适合短距；DWDM 栅格密到 100 GHz 一档，一根纤能塞几十上百个通道，但要稳频与放大。</span></p><h3 id="模块不转发" tabindex="-1">模块不转发 <a class="header-anchor" href="#模块不转发" aria-label="Permalink to &quot;模块不转发&quot;">​</a></h3><p>可插拔只做电光适配；WDM 把一根纤变成多条逻辑波长。口 down 往往先于 ICMP。波长调度是光学运营，不进 TCP。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：ASIC SerDes → 金手指 → 激光/调制器 → 光纤；反向 PIN/APD → CDR → 电。WDM：合波/分波器放在模块外或可调模块内。管理：I2C 读光功率、温度，供链路诊断，不是控制平面协议。</p>',12)),(t(),n(d,null,{default:s(()=>[o(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SER%5B%22%E7%94%B5%20SerDes%22%5D%20--%3E%20MOD%5B%22%E5%85%89%E6%A8%A1%E5%9D%97%22%5D%0A%20%20MOD%20--%3E%20LAM%5B%22%E6%B3%A2%E9%95%BF%22%5D%0A%20%20LAM%20--%3E%20MUX%5B%22WDM%20%E5%90%88%E6%B3%A2%22%5D%0A%20%20MUX%20--%3E%20FIB%5B%22%E4%B8%80%E6%A0%B9%E7%BA%A4%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"数字实例：容量账怎么算——单波 100 Gb/s，乘 80 个 DWDM 通道，一根纤约 8 Tb/s。但它不是无限乘法：通道越密，滤波器串扰与光纤非线性越差，所以「每波长的 \\(C\\) × 波长数」只是近似上限。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[r("分层：换模块不换 MAC 地址。故障：光功率低先表现为 PCS 丢锁，再表现为口 down。主干"),e("a",{href:"/cs/icmp"},"ICMP"),r(" 的不可达是 IP 层的；本课的 down 更早。WDM 把「一条光纤」变成多条逻辑链路，生成树与 IP 仍按逻辑口看。")],-1)),a[6]||(a[6]=e("p",null,"灰光点到点最简单；彩光把波长当资源调度，运维进入光学，不进入 TCP。",-1)),a[7]||(a[7]=e("p",null,"链路坏了，故障在哪一层最先被看见：",-1)),(t(),n(d,null,{default:s(()=>[o(l,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20LR%0A%20%20PWR%5B%22%E5%85%89%E5%8A%9F%E7%8E%87%E5%BC%82%E5%B8%B8%22%5D%20--%3E%20PCS%5B%22PCS%20%E4%B8%A2%E9%94%81%22%5D%0A%20%20PCS%20--%3E%20DOWN%5B%22%E5%8F%A3%20down%22%5D%0A%20%20DOWN%20--%3E%20IP%5B%22ICMP%20%E4%B8%8D%E5%8F%AF%E8%BE%BE%22%5D%0A%20%20MON%5B%22I2C%20%E8%AF%BB%E5%85%89%E5%8A%9F%E7%8E%87%2F%E6%B8%A9%E5%BA%A6%22%5D%20-.%20%22%E6%9C%80%E6%97%A9%E7%9C%8B%E8%A7%81%22%20.-%20PWR%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=i('<p><span class="marginnote">常见误区：初学者一遇断网先 ping。其实光模块衰减 → PCS 丢锁 → 口 down 在 IP 层之前就已发生，ping 只是最后一个报丧的。先读 I2C 光功率（收发各多少 dBm），再谈 IP 诊断。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 ROADMs 的全网波长路由算法。以太网速率档与编码演进是下一课。后课默认：可插拔模块 = 电光适配；WDM = 波长并行。</p><p>不要把「400G ZR 相干」写成已在接入交换机普及——距离与功耗把场景钉在 DCI。</p><p>下一课<a href="/cs/ethernet-speeds">以太网速率演进</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>光模块标准化电接口，光侧按距离与波长选型。</li><li>WDM 用波长并行逼近光纤的可用 \\(B\\)。</li><li>模块不转发；口 down 往往先于 IP 诊断。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：ITU-T G.694.1；IEEE 802.3；SFF/CMIS。</li></ul>',7))])}const S=p(m,[["render",A]]);export{u as __pageData,S as default};
